const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const R = data[idx++];
const N = data[idx++];

const minPrice = new Map();

for (let i = 0; i < N; i++) {
  const type = data[idx++];
  const price = data[idx++];

  if (!minPrice.has(type) || price < minPrice.get(type)) {
    minPrice.set(type, price);
  }
}

const prices = Array.from(minPrice.values()).sort((a, b) => a - b);

let total = 0;
let count = 0;

for (const price of prices) {
  if (total + price <= R) {
    total += price;
    count++;
  } else {
    break;
  }
}

console.log(count);
